package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StrBuilder#contains(char)
 */
public class StrBuilder_contains_TriageGen2Test {

    @Test
    public void testContains_EmptyBuilder_ReturnsFalse() {
        StrBuilder sb = new StrBuilder();
        assertFalse("Should return false for an empty builder", sb.contains('a'));
    }

    @Test
    public void testContains_CharExistsAtStart_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("abc");
        assertTrue("Should return true when char is at the beginning", sb.contains('a'));
    }

    @Test
    public void testContains_CharExistsInMiddle_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("abc");
        assertTrue("Should return true when char is in the middle", sb.contains('b'));
    }

    @Test
    public void testContains_CharExistsAtEnd_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("abc");
        assertTrue("Should return true when char is at the end", sb.contains('c'));
    }

    @Test
    public void testContains_CharDoesNotExist_ReturnsFalse() {
        StrBuilder sb = new StrBuilder("abc");
        assertFalse("Should return false when char is not present", sb.contains('z'));
    }

    @Test
    public void testContains_MultipleOccurrences_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("aaaaa");
        assertTrue("Should return true when char appears multiple times", sb.contains('a'));
    }

    @Test
    public void testContains_SpecialCharacters_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("\n\t ");
        assertTrue("Should find newline", sb.contains('\n'));
        assertTrue("Should find tab", sb.contains('\t'));
        assertTrue("Should find space", sb.contains(' '));
    }

    @Test
    public void testContains_AfterAppend_ReturnsTrue() {
        StrBuilder sb = new StrBuilder();
        sb.append("hello");
        assertTrue("Should find char after append", sb.contains('e'));
    }

    @Test
    public void testContains_AfterClear_ReturnsFalse() {
        StrBuilder sb = new StrBuilder("test");
        sb.clear();
        assertFalse("Should return false after clearing the builder", sb.contains('t'));
    }

    @Test
    public void testContains_CaseSensitivity_ReturnsFalse() {
        StrBuilder sb = new StrBuilder("ABC");
        assertFalse("Should be case sensitive", sb.contains('a'));
    }
}
